style.css:
@-moz-document domain("gemini.google.com") {
/* Base Variables & Root Overrides */
    :root, body {
        /* Warm paper backgrounds */
        --md-sys-color-surface: #f4ecd8 !important;
        --md-sys-color-background: #f4ecd8 !important;
        --md-sys-color-surface-container: #e8dcca !important;
        --md-sys-color-surface-container-high: #e8dcca !important;
        --md-sys-color-surface-container-low: #f4ecd8 !important;
        --md-sys-color-surface-variant: #e3d1bc !important;

        /* Soft dark brown text (avoids harsh pure black) */
        --md-sys-color-on-surface: #433422 !important;
        --md-sys-color-on-background: #433422 !important;
        --md-sys-color-on-surface-variant: #5c4b37 !important;
        
        /* General page setup */
        background-color: #f4ecd8 !important;
        color: #433422 !important;
    }

    /* Force background colors on main structural elements */
    body, main, header, nav, [role="main"], [role="navigation"], [role="banner"] {
        background-color: #f4ecd8 !important;
    }

    /* Force text color on all text elements */
    h1, h2, h3, h4, h5, h6, p, span, div, li {
        color: #433422 !important;
    }

    /* Chat Input Box & Sidebars */
    textarea, [role="textbox"], .action-container, aside {
        background-color: #e8dcca !important;
        color: #433422 !important;
        border-color: #d6c5b3 !important;
    }

    /* Code Blocks (Slightly darker sepia to stand out) */
    pre, code, [class*="code-block"] {
        background-color: #e3d1bc !important;
        color: #2b2116 !important;
        border: 1px solid #d6c5b3 !important;
    }

    /* Links */
    a {
        color: #9c5c14 !important;
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }

    /* Buttons */
    button, [role="button"] {
        background-color: #e8dcca !important;
        color: #433422 !important;
        border: 1px solid #d6c5b3 !important;
        transition: 0.2s !important;
    }
    
    button:hover, [role="button"]:hover {
        background-color: #d6c5b3 !important;
    }

    /* Soften Icons */
    svg {
        fill: #5c4b37 !important;
        color: #5c4b37 !important;
    }

    /* Scrollbars (Webkit/Chrome) */
    ::-webkit-scrollbar {
        width: 10px !important;
        background: #f4ecd8 !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #d6c5b3 !important;
        border-radius: 5px !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #bfae99 !important;
    }
}
